'use client';

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ShoppingCart, X, Trash, Phone, MapPin, Send, CreditCard } from 'lucide-react';

/**
 * POWER-UP: CART V1 (WHATSAPP LITE) - DARK EDITION
 * Carrito flotante, persistente (localStorage) con checkout directo a WhatsApp.
 */

export interface CartItem {
    id: string;
    name: string;
    price: number;
    qty: number;
    image?: string;
}

interface CartV1Props {
    data?: any;
    whatsappNumber?: string;
    currency?: string;
    primaryColor?: string;
}

export const CartV1_WhatsApp = ({
    data = {},
    whatsappNumber = "549381000000",
    currency = "$",
    primaryColor = "#4F46E5"
}: CartV1Props) => {

    const [cart, setCart] = useState<CartItem[]>(data.products || []);
    const [isOpen, setIsOpen] = useState(false);
    
    const [clientName, setClientName] = useState('');
    const [clientAddress, setClientAddress] = useState('');

    useEffect(() => {
        const saved = localStorage.getItem('stitch_cart');
        if (saved) {
            try {
                const parsed = JSON.parse(saved);
                if (parsed.length > 0) setCart(parsed);
            } catch (e) {
                console.error("Cart corrupted", e);
            }
        }
    }, []);

    useEffect(() => {
        localStorage.setItem('stitch_cart', JSON.stringify(cart));
    }, [cart]);

    useEffect(() => {
        const handleAddToCart = (e: CustomEvent<CartItem>) => {
            const newItem = e.detail;
            setCart(prev => {
                const existing = prev.find(p => p.id === newItem.id);
                if (existing) {
                    return prev.map(p => p.id === newItem.id ? { ...p, qty: p.qty + 1 } : p);
                }
                return [...prev, { ...newItem, qty: 1 }];
            });
        };

        window.addEventListener('stitch-add-to-cart' as any, handleAddToCart);
        return () => window.removeEventListener('stitch-add-to-cart' as any, handleAddToCart);
    }, []);

    const removeFromCart = (id: string) => {
        setCart(prev => prev.filter(p => p.id !== id));
    };

    const updateQty = (id: string, delta: number) => {
        setCart(prev => prev.map(p => {
            if (p.id === id) return { ...p, qty: Math.max(1, p.qty + delta) };
            return p;
        }));
    };

    const checkout = () => {
        if (cart.length === 0) return;
        let message = `Hola! Soy *${clientName || 'Cliente'}*. Quiero hacer el siguiente pedido:\n\n`;
        cart.forEach(p => {
            message += `▪️ ${p.qty}x ${p.name} ($${(p.price * p.qty).toLocaleString()})\n`;
        });
        const total = cart.reduce((sum, p) => sum + (p.price * p.qty), 0);
        message += `\n💰 *TOTAL ESTIMADO: ${currency}${total.toLocaleString()}*`;
        if (clientAddress) message += `\n📍 Envío a: ${clientAddress}`;
        const url = `https://wa.me/${whatsappNumber}?text=${encodeURIComponent(message)}`;
        window.open(url, '_blank');
    };

    const totalQty = cart.reduce((sum, p) => sum + p.qty, 0);
    const totalPrice = cart.reduce((sum, p) => sum + (p.price * p.qty), 0);

    return (
        <>
            <AnimatePresence>
                {totalQty > 0 && (
                    <motion.div 
                        initial={{ scale: 0, opacity: 0, rotate: -45 }}
                        animate={{ scale: 1, opacity: 1, rotate: 0 }}
                        exit={{ scale: 0, opacity: 0, rotate: 45 }}
                        className="fixed bottom-10 right-10 z-[10001]"
                    >
                        <button 
                            onClick={() => setIsOpen(true)}
                            className="relative bg-slate-900 text-white p-6 rounded-[2.5rem] shadow-[0_20px_60px_rgba(0,0,0,0.6)] hover:scale-110 active:scale-95 transition-all border border-white/20 group"
                        >
                            <ShoppingCart size={32} />
                            <span className="absolute -top-3 -right-3 bg-red-600 text-white text-[10px] font-black w-8 h-8 rounded-2xl flex items-center justify-center border-4 border-slate-900 shadow-xl group-hover:rotate-12 transition-transform">
                                {totalQty}
                            </span>
                        </button>
                    </motion.div>
                )}
            </AnimatePresence>

            <AnimatePresence>
                {isOpen && (
                    <div className="fixed inset-0 z-[10002] flex justify-end">
                        <motion.div 
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            exit={{ opacity: 0 }}
                            onClick={() => setIsOpen(false)}
                            className="absolute inset-0 bg-slate-950/80 backdrop-blur-md"
                        />

                        <motion.div 
                            initial={{ x: '100%' }}
                            animate={{ x: 0 }}
                            exit={{ x: '100%' }}
                            transition={{ type: 'spring', damping: 30, stiffness: 200 }}
                            className="relative w-full max-w-md bg-slate-900 border-l border-white/5 shadow-2xl h-full flex flex-col z-[10003] overflow-hidden"
                        >
                            <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-600/10 rounded-full blur-[100px] pointer-events-none" />
                            
                            <div className="p-10 border-b border-white/5 flex justify-between items-center bg-slate-900/40 relative z-10">
                                <div>
                                    <span className="text-[10px] font-black tracking-[0.4em] text-indigo-400 uppercase mb-1 block">Checkout System</span>
                                    <h3 className="text-2xl font-black text-white tracking-tighter italic">Tu Pedido</h3>
                                </div>
                                <button onClick={() => setIsOpen(false)} className="bg-white/5 p-3 rounded-2xl hover:bg-red-500/20 text-slate-400 hover:text-red-500 transition-all border border-white/5">
                                    <X size={20} />
                                </button>
                            </div>

                            <div className="flex-1 overflow-y-auto p-8 space-y-6 custom-scrollbar relative z-10">
                                {cart.length === 0 ? (
                                    <div className="text-center py-20 opacity-30 space-y-4">
                                        <ShoppingCart size={64} className="mx-auto text-slate-500"/>
                                        <p className="font-black uppercase tracking-[0.2em] text-[10px]">El vacío de la soberanía</p>
                                    </div>
                                ) : (
                                    cart.map(item => (
                                        <motion.div 
                                            layout
                                            key={item.id} 
                                            className="group flex gap-5 bg-slate-950/50 p-4 rounded-[2rem] border border-white/5 hover:border-indigo-500/30 transition-all"
                                        >
                                            <div className="h-20 w-20 bg-slate-900 rounded-2xl shrink-0 bg-center bg-cover border border-white/5" style={{ backgroundImage: `url(${item.image})` }} />
                                            
                                            <div className="flex-1 min-w-0 flex flex-col justify-between py-1">
                                                <div className="flex justify-between items-start">
                                                    <h4 className="font-bold text-sm text-white truncate pr-2 tracking-tight italic uppercase">{item.name}</h4>
                                                    <button onClick={() => removeFromCart(item.id)} className="text-slate-600 hover:text-red-500 transition-colors"><Trash size={16}/></button>
                                                </div>
                                                
                                                <div className="flex justify-between items-end">
                                                    <p className="text-xs font-black text-indigo-400">{currency}{item.price.toLocaleString()}</p>
                                                    
                                                    <div className="flex items-center gap-4 bg-white/5 rounded-xl px-3 py-1.5 border border-white/5">
                                                        <button onClick={() => updateQty(item.id, -1)} className="text-slate-500 hover:text-white font-black text-sm">-</button>
                                                        <span className="text-xs font-black text-white w-4 text-center">{item.qty}</span>
                                                        <button onClick={() => updateQty(item.id, 1)} className="text-slate-500 hover:text-white font-black text-sm">+</button>
                                                    </div>
                                                </div>
                                            </div>
                                        </motion.div>
                                    ))
                                )}
                            </div>

                            <div className="p-10 bg-slate-950/80 backdrop-blur-2xl border-t border-white/5 space-y-8 relative z-10">
                                <div className="flex justify-between items-end">
                                    <div>
                                        <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-1">Inversión Total</p>
                                        <div className="text-4xl font-black text-white tracking-tighter italic">{currency}{totalPrice.toLocaleString()}</div>
                                    </div>
                                    <div className="bg-indigo-600/10 border border-indigo-500/20 px-3 py-1 rounded-lg text-indigo-400 text-[9px] font-black uppercase tracking-widest">
                                        Estimate
                                    </div>
                                </div>
                                
                                <div className="space-y-4">
                                     <div className="relative">
                                        <input 
                                            type="text" 
                                            value={clientName}
                                            onChange={(e) => setClientName(e.target.value)}
                                            placeholder="Nombre del Soberano" 
                                            className="w-full bg-white/5 border border-white/5 p-5 rounded-2xl text-sm italic focus:border-indigo-500 outline-none transition-all text-white placeholder:text-slate-700"
                                        />
                                     </div>
                                     <div className="relative">
                                        <input 
                                            type="text" 
                                            value={clientAddress}
                                            onChange={(e) => setClientAddress(e.target.value)}
                                            placeholder="Coordenadas de Entrega" 
                                            className="w-full bg-white/5 border border-white/5 p-5 rounded-2xl text-sm italic focus:border-indigo-500 outline-none transition-all text-white placeholder:text-slate-700"
                                        />
                                     </div>
                                </div>

                                <button 
                                    onClick={checkout}
                                    disabled={cart.length === 0}
                                    className="w-full bg-[#25D366] hover:bg-[#22c35e] text-white font-black py-5 rounded-[2rem] transition-all flex items-center justify-center gap-3 shadow-xl shadow-green-600/20 disabled:opacity-20 disabled:grayscale uppercase tracking-[0.2em] text-[12px]"
                                >
                                    Enviar a WhatsApp
                                    <Send size={20} />
                                </button>
                            </div>
                        </motion.div>
                    </div>
                )}
            </AnimatePresence>
        </>
    );
};
