'use client';

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Calendar, Clock, Check, X, ChevronLeft, ChevronRight } from 'lucide-react';

/**
 * WIDGET: BOOKING V1 (TURNERO WHATSAPP)
 * Sistema de reservas con calendario, selección de hora y confirmación.
 */

interface BookingV1Props {
    title?: string;
    description?: string;
    ctaText?: string;
    whatsappNumber?: string;
    themeColor?: string;
}

const DAYS = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];
const MONTHS = ['Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio', 'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'];
const WORK_DAYS = [1, 2, 3, 4, 5, 6]; 
const START_HOUR = 10;
const END_HOUR = 20;

export const BookingV1_Turnero = ({
    title = "Reservá tu Turno",
    description = "Seleccioná el día y horario que mejor te convenga.",
    ctaText = "Ver Disponibilidad",
    whatsappNumber = "549381000000",
    themeColor = "#D4AF37"
}: BookingV1Props) => {

    const [isOpen, setIsOpen] = useState(false);
    const [step, setStep] = useState(1);
    const [currentDate, setCurrentDate] = useState(new Date());
    const [selectedDate, setSelectedDate] = useState<Date | null>(null);
    const [selectedTime, setSelectedTime] = useState<string | null>(null);
    const [clientName, setClientName] = useState('');

    // Calendar Helper Functions
    const getDaysInMonth = (date: Date) => {
        const year = date.getFullYear();
        const month = date.getMonth();
        const days = new Date(year, month + 1, 0).getDate();
        const firstDay = new Date(year, month, 1).getDay();
        return { days, firstDay, year, month };
    };

    const handleDateSelect = (day: number) => {
        const newDate = new Date(currentDate.getFullYear(), currentDate.getMonth(), day);
        setSelectedDate(newDate);
        setStep(2);
    };

    const handleTimeSelect = (time: string) => {
        setSelectedTime(time);
        setStep(3);
    };

    const handleWhatsAppRedirect = () => {
        if (!selectedDate || !selectedTime) return;
        const dateStr = selectedDate.toLocaleDateString('es-AR', { weekday: 'long', day: 'numeric', month: 'long' });
        const text = encodeURIComponent(`Hola! Quiero reservar turno para el ${dateStr} a las ${selectedTime} hs. Soy ${clientName || 'Cliente'}.`);
        window.open(`https://wa.me/${whatsappNumber}?text=${text}`, '_blank');
        setIsOpen(false);
        setStep(1);
    };

    const renderCalendarGrid = () => {
        const { days, firstDay } = getDaysInMonth(currentDate);
        const today = new Date();
        today.setHours(0,0,0,0);

        const grid = [];
        // Empty slots
        for (let i = 0; i < firstDay; i++) {
            grid.push(<div key={`empty-${i}`} className="aspect-square" />);
        }

        // Days
        for (let day = 1; day <= days; day++) {
            const date = new Date(currentDate.getFullYear(), currentDate.getMonth(), day);
            const isPast = date < today;
            const isWorkDay = WORK_DAYS.includes(date.getDay());
            const isToday = date.toDateString() === today.toDateString();

            grid.push(
                <button
                    key={day}
                    disabled={isPast || !isWorkDay}
                    onClick={() => handleDateSelect(day)}
                    className={`
                        aspect-square rounded-lg text-sm font-medium transition-all flex items-center justify-center
                        ${isToday ? `ring-2 ring-[${themeColor}] font-bold` : ''}
                        ${!isPast && isWorkDay 
                            ? `hover:bg-[${themeColor}] hover:text-white bg-gray-100 text-gray-800` 
                            : 'text-gray-300 cursor-not-allowed opacity-50'}
                    `}
                    style={(!isPast && isWorkDay && !isToday) ? {} : { borderColor: themeColor }}
                >
                    {day}
                </button>
            );
        }
        return grid;
    };

    const renderTimeSlots = () => {
        const slots = [];
        for (let h = START_HOUR; h < END_HOUR; h++) {
            const time = `${h.toString().padStart(2, '0')}:00`;
            slots.push(
                <button
                    key={time}
                    onClick={() => handleTimeSelect(time)}
                    className="p-3 bg-gray-50 rounded-xl hover:bg-black hover:text-white transition-all text-gray-700 font-medium"
                >
                    {time}
                </button>
            );
        }
        return slots;
    };

    return (
        <section className="py-24 px-4 bg-white text-center border-t border-gray-100">
            <div className="container mx-auto px-4 max-w-4xl">
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    whileInView={{ opacity: 1, y: 0 }}
                    viewport={{ once: true }}
                >
                    <h2 className="text-3xl md:text-5xl font-black mb-6 text-gray-900 tracking-tighter">{title}</h2>
                    <p className="text-xl text-gray-500 mb-10 max-w-2xl mx-auto">{description}</p>
                    
                    <button 
                        onClick={() => setIsOpen(true)}
                        className="text-white font-bold py-5 px-10 rounded-full shadow-xl hover:scale-105 active:scale-95 transition-all text-lg flex items-center justify-center gap-3 mx-auto"
                        style={{ backgroundColor: themeColor }}
                    >
                        <Calendar size={24} />
                        {ctaText}
                    </button>
                </motion.div>
            </div>

            {/* MODAL */}
            <AnimatePresence>
                {isOpen && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center px-4">
                        <motion.div 
                            initial={{ opacity: 0 }} 
                            animate={{ opacity: 1 }} 
                            exit={{ opacity: 0 }} 
                            onClick={() => setIsOpen(false)}
                            className="absolute inset-0 bg-black/60 backdrop-blur-sm" 
                        />
                        
                        <motion.div 
                            initial={{ scale: 0.9, opacity: 0 }}
                            animate={{ scale: 1, opacity: 1 }}
                            exit={{ scale: 0.9, opacity: 0 }}
                            className="relative bg-white text-gray-800 rounded-4xl w-full max-w-md p-8 shadow-2xl overflow-hidden"
                        >
                            <button onClick={() => setIsOpen(false)} className="absolute top-6 right-6 text-gray-400 hover:text-gray-900 transition-colors">
                                <X size={24} />
                            </button>

                            {/* Header */}
                            <div className="flex items-center gap-3 mb-8" style={{ color: themeColor }}>
                                <Calendar size={28} />
                                <h3 className="font-bold text-2xl text-gray-900">Reservar Turno</h3>
                            </div>

                            {/* STEP 1: CALENDAR */}
                            {step === 1 && (
                                <div className="space-y-6">
                                    <div className="flex justify-between items-center">
                                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1))} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><ChevronLeft /></button>
                                        <span className="font-bold text-lg capitalize text-gray-900">{MONTHS[currentDate.getMonth()]} {currentDate.getFullYear()}</span>
                                        <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1))} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><ChevronRight /></button>
                                    </div>
                                    
                                    <div className="grid grid-cols-7 gap-2 text-center">
                                        {DAYS.map(d => <span key={d} className="text-xs font-bold text-gray-400 uppercase tracking-wider">{d}</span>)}
                                    </div>
                                    
                                    <div className="grid grid-cols-7 gap-2">
                                        {renderCalendarGrid()}
                                    </div>
                                </div>
                            )}

                            {/* STEP 2: TIME */}
                            {step === 2 && (
                                <div className="space-y-6">
                                    <div className="text-center">
                                        <p className="text-gray-400 text-sm uppercase tracking-widest font-bold mb-1">Fecha Seleccionada</p>
                                        <h4 className="text-2xl font-black text-gray-900 capitalize mb-6">
                                            {selectedDate?.toLocaleDateString('es-AR', { weekday: 'long', day: 'numeric', month: 'long' })}
                                        </h4>
                                    </div>
                                    <div className="grid grid-cols-3 gap-3 max-h-60 overflow-y-auto custom-scrollbar">
                                        {renderTimeSlots()}
                                    </div>
                                    <button onClick={() => setStep(1)} className="w-full py-3 text-gray-400 font-bold hover:text-gray-900 transition-colors">
                                        ← Volver al Calendario
                                    </button>
                                </div>
                            )}

                            {/* STEP 3: CONFIRM */}
                            {step === 3 && (
                                <div className="space-y-6">
                                    <div className="bg-gray-50 p-6 rounded-3xl border border-gray-100">
                                        <div className="flex items-start gap-4 mb-4">
                                            <div className="p-3 bg-white rounded-xl shadow-sm"><Calendar size={20} className="text-gray-400"/></div>
                                            <div>
                                                <p className="text-xs text-gray-400 font-bold uppercase tracking-wider">Fecha</p>
                                                <p className="font-bold text-gray-900 capitalize">{selectedDate?.toLocaleDateString('es-AR', { weekday: 'long', day: 'numeric', month: 'long' })}</p>
                                            </div>
                                        </div>
                                        <div className="flex items-start gap-4">
                                            <div className="p-3 bg-white rounded-xl shadow-sm"><Clock size={20} className="text-gray-400"/></div>
                                            <div>
                                                <p className="text-xs text-gray-400 font-bold uppercase tracking-wider">Hora</p>
                                                <p className="font-bold text-gray-900">{selectedTime} hs</p>
                                            </div>
                                        </div>
                                    </div>

                                    <div className="space-y-2">
                                        <label className="text-xs font-bold text-gray-400 uppercase tracking-wider ml-1">Tu Nombre (Opcional)</label>
                                        <input 
                                            type="text" 
                                            value={clientName}
                                            onChange={(e) => setClientName(e.target.value)}
                                            placeholder="Juan Pérez"
                                            className="w-full p-4 border border-gray-200 rounded-xl focus:ring-2 outline-none font-medium text-gray-900"
                                            style={{ '--tw-ring-color': themeColor } as React.CSSProperties}
                                        />
                                    </div>

                                    <button 
                                        onClick={handleWhatsAppRedirect}
                                        className="w-full bg-[#25D366] text-white font-bold py-5 rounded-xl hover:bg-[#20bd5a] flex items-center justify-center gap-2 shadow-xl hover:shadow-2xl transition-all"
                                    >
                                        COFIRMAR RESERVA
                                        <Check size={20} />
                                    </button>
                                    
                                    <button onClick={() => setStep(2)} className="w-full py-3 text-gray-400 font-bold hover:text-gray-900 transition-colors">
                                        ← Cambiar Hora
                                    </button>
                                </div>
                            )}

                        </motion.div>
                    </div>
                )}
            </AnimatePresence>
        </section>
    );
};
